import numpy as np
# dW: the 252 seeded increments, dt = 1/252 (provided)

def euler_gbm(S0, mu, sigma, dW, dt):
    """All n + 1 prices of S_{k+1} = S_k (1 + mu dt + sigma dW_k)."""
    dW = np.asarray(dW, dtype=float)
    return S0 * np.concatenate([[1.0], np.cumprod(1 + mu * dt + sigma * dW)])

def exact_gbm(S0, mu, sigma, dW, dt):
    """All n + 1 prices S0 exp((mu - sigma^2 / 2) t + sigma W_t)."""
    dW = np.asarray(dW, dtype=float)
    n = len(dW)
    t = np.arange(n + 1) * dt
    W = np.concatenate([[0.0], np.cumsum(dW)])
    return S0 * np.exp((mu - sigma ** 2 / 2) * t + sigma * W)
